insert into public.faqs (question, answer, category, sort_order) values
  ('Apa itu PADU Printing?', 'PADU Printing adalah jasa percetakan digital di Jakarta Timur yang membantu bisnis, perusahaan, event, dan kebutuhan personal menghasilkan media cetak profesional, konsisten, dan siap memperkuat visual brand Anda. Layanan kami meliputi banner dan spanduk, kartu nama, stiker, undangan, kaos, hingga merchandise custom.', 'Umum', 1),
  ('Di mana lokasi PADU Printing?', 'Berlokasi di Jl. Otista Raya No. 170, RT.2/RW.8, Bidara Cina, Jakarta Timur, DKI Jakarta 13330. Butuh petunjuk arah? Hubungi kami via WhatsApp dan tim akan membantu.', 'Umum', 2),
  ('Apa keunggulan PADU Printing?', 'Tiga keunggulan utama: kualitas cetak tajam dengan warna akurat, proses pengerjaan cepat dan tepat waktu, serta layanan yang ramah dan siap membantu mulai dari konsultasi hingga pengiriman.', 'Umum', 3),
  ('Kenapa harus memilih PADU Printing dibanding percetakan lain?', 'Karena kami mengutamakan kecepatan eksekusi tanpa mengorbankan kualitas. Dari kartu nama, banner, undangan, hingga merchandise custom dikerjakan dengan hasil yang konsisten, ditambah pelayanan setiap hari dan konsultasi gratis untuk menentukan spesifikasi yang tepat.', 'Umum', 4),
  ('Apakah PADU Printing cocok untuk kebutuhan mendadak atau deadline?', 'Cocok. PADU Printing melayani pemesanan setiap hari tanpa henti, jadi kebutuhan cetak mendadak seperti banner acara dadakan atau kelengkapan acara bisa tetap dikerjakan tanpa harus menunggu jam operasional.', 'Umum', 5),
  ('Apakah PADU Printing punya artikel atau tips seputar percetakan?', 'Ya, tersedia halaman Artikel yang berisi tips seputar percetakan, desain, dan kebutuhan promosi bisnis, mulai dari perbandingan media promosi, panduan memilih produk cetak, hingga cara menyiapkan file desain.', 'Umum', 6),
  ('Apakah ada garansi hasil cetak?', 'Ada. Jika terjadi kesalahan yang berasal dari pihak kami, seperti salah cetak atau hasil produksi yang rusak, garansi cetak ulang akan kami berikan tanpa biaya tambahan.', 'Umum', 7),
  ('Bagaimana cara memesan cetakan?', 'Bisa pesan online via WhatsApp atau datang langsung ke lokasi. Prosesnya: pilih produk dan tentukan spesifikasinya, kirim file desain ke tim, lalu lakukan pembayaran setelah pesanan dikonfirmasi admin.', 'Pemesanan', 8),
  ('Bagaimana cara menghubungi PADU Printing?', 'Bisa melalui WhatsApp di 0821-2349-6469. Tim admin siap membantu mulai dari pemilihan produk hingga proses pemesanan.', 'Pemesanan', 9),
  ('Apakah bisa konsultasi produk sebelum memesan?', 'Bisa. Tersedia layanan konsultasi gratis via WhatsApp untuk membantu menentukan produk, bahan, dan spesifikasi yang paling sesuai dengan kebutuhan serta budget Anda.', 'Pemesanan', 10),
  ('Apakah bisa pesan dalam quantity kecil?', 'Tergantung jenis produk. Sebagian produk bisa dipesan dengan quantity kecil, sementara produk merchandise tertentu memiliki jumlah minimal order. Admin akan menginformasikan minimal order sesuai produk yang dipilih.', 'Pemesanan', 11),
  ('Apakah bisa urgent order?', 'Bisa, dengan menyesuaikan ketersediaan slot produksi. Hubungi admin terlebih dahulu untuk menanyakan ketersediaan dan perkiraan waktu pengerjaan.', 'Pemesanan', 12),
  ('Produk apa saja yang dilayani PADU Printing?', 'Antara lain cetak banner dan spanduk, X-banner, roll banner, kartu nama, stiker dan label, undangan, kaos dan seragam, mug, tumbler, tote bag, payung, blocknote, pin, hingga box packaging dan paper bag custom.', 'Produk', 13),
  ('Apakah bisa cetak banner atau spanduk untuk display pameran dan dekorasi?', 'Bisa. Banner vinil indoor maupun outdoor cocok untuk display toko, poster pameran, dan dekorasi acara. Sifatnya ringan dan mudah dipasang, namun tetap kokoh dan tahan lama.', 'Produk', 14),
  ('Apakah bisa cetak bendera custom?', 'Bisa. Tersedia cetak spanduk bendera custom dengan bahan vinil tebal dan warna tajam, cocok untuk promosi toko, acara, kantor, maupun komunitas.', 'Produk', 15),
  ('Apakah bisa cetak X-Banner dan Roll Up Banner?', 'Bisa. Tersedia X-Banner custom untuk kebutuhan promosi yang ekonomis serta Roll Up Banner yang lebih praktis dibawa dan dipasang berulang kali untuk berbagai event.', 'Produk', 16),
  ('Apa bedanya X-Banner dengan Roll Up Banner?', 'Perbedaannya terletak pada harga, kepraktisan, dan ketahanan. X-Banner umumnya lebih ekonomis, sedangkan Roll Up Banner lebih rapi, praktis dibawa, dan bisa digunakan berulang untuk promosi di banyak tempat.', 'Produk', 17),
  ('Bagaimana memilih antara banner, X-banner, atau spanduk untuk promosi?', 'Pemilihan tergantung di mana media akan dipasang, berapa lama akan digunakan, dan berapa anggaran yang tersedia. Konsultasikan tujuan promosi Anda ke tim agar mendapat rekomendasi media yang paling efektif.', 'Produk', 18),
  ('Apakah harga murah berarti kualitas cetaknya asal-asalan?', 'Tidak. Harga terjangkau dan kualitas tajam bisa didapat bersamaan asalkan spesifikasi bahan disesuaikan dengan kebutuhan, bukan asal memilih bahan termurah atau termahal. Tim kami siap membantu memilihkan kombinasi yang tepat.', 'Produk', 19),
  ('Apakah bisa cetak kartu nama premium?', 'Bisa. Terdapat berbagai pilihan bahan dan finishing premium, mulai dari art carton, ivory, hingga kartu nama plastik PVC, serta finishing seperti spot UV agar kartu nama tampil profesional.', 'Produk', 20),
  ('Apakah bisa cetak kartu PVC atau kartu nama plastik?', 'Bisa. Kartu PVC dicetak dengan bahan plastik tebal yang tahan lama, cocok untuk kartu nama premium maupun kebutuhan kartu identitas yang awet dengan hasil profesional.', 'Produk', 21),
  ('Apakah bisa cetak blocknote custom?', 'Bisa. Blocknote custom dengan cover logo tersedia untuk kebutuhan seperti company profile ringkas, katalog, dan merchandise seminar, dengan hasil cetak yang rapi dan berkualitas.', 'Produk', 22),
  ('Apakah bisa cetak kartu ucapan custom?', 'Bisa. Kartu ucapan A6 dengan berbagai pilihan bahan dan finishing tersedia untuk momen spesial, hadiah korporat, maupun merchandise kenang-kenangan.', 'Produk', 23),
  ('Apakah bisa cetak undangan custom?', 'Bisa. Undangan pernikahan, ulang tahun, sunatan, dan wedding card tersedia dengan berbagai pilihan bahan dan finishing agar momen spesial terasa lebih berkesan.', 'Produk', 24),
  ('Apakah bisa cetak stiker dan label custom?', 'Bisa. Stiker vinyl cutting, stiker kertas, label botol, dan stiker bulat tersedia untuk kebutuhan packaging produk maupun media promosi.', 'Produk', 25),
  ('Apakah bisa cetak stiker transparan? Untuk apa kegunaannya?', 'Bisa. Stiker transparan adalah media cetak tembus pandang yang cocok untuk window display, branding kaca toko, dan dekorasi, karena tetap mempertahankan warna latar tempatnya dipasang dan tampil tajam.', 'Produk', 26),
  ('Apakah bisa membuat pin custom untuk identitas komunitas?', 'Bisa. Pin custom logam full color tersedia untuk kebutuhan identitas instansi, sekolah, komunitas, hingga souvenir acara, dengan hasil yang presisi dan tahan lama.', 'Produk', 27),
  ('Apakah bisa cetak merchandise seperti mug custom?', 'Bisa. Mug custom full color bisa dicetak logo, foto, nama, atau ilustrasi. Cocok untuk souvenir, corporate gift, hingga merchandise komunitas.', 'Produk', 28),
  ('Apakah bisa branding tumbler custom untuk perusahaan?', 'Bisa. Tumbler custom bisa dibranding dengan logo perusahaan melalui beberapa metode pengerjaan. Cocok untuk meningkatkan identitas merek lewat merchandise yang dipakai sehari-hari.', 'Produk', 29),
  ('Apakah bisa cetak tote bag atau tas kanvas custom?', 'Bisa. Tote bag kanvas sablon ringan, kuat, dan bisa dipakai berulang. Cocok untuk seminar, pameran, event, atau sebagai alternatif ramah lingkungan pengganti tas plastik.', 'Produk', 30),
  ('Apakah bisa cetak payung custom untuk acara?', 'Bisa. Payung lipat custom full color bisa dicetak logo atau slogan untuk seminar, pameran, konser, pernikahan, dan event lainnya, sekaligus merchandise yang awet dan tetap berguna.', 'Produk', 31),
  ('Apakah bisa cetak box custom untuk kemasan?', 'Bisa. Tersedia box custom untuk kemasan produk, box makanan, dan box gift dengan hasil kokoh serta desain yang disesuaikan dengan kebutuhan brand Anda.', 'Produk', 32),
  ('Apakah tersedia jasa cetak paper bag custom untuk perusahaan?', 'Ya, tersedia cetak paper bag custom logo perusahaan dengan eksekusi cepat. Cocok untuk branding, kemasan produk, hingga acara korporat.', 'Produk', 33),
  ('Apakah bisa cetak kaos dan seragam custom?', 'Bisa. Kaos polos, kaos tim, jersey, hingga seragam kantor bisa disablon dengan desain custom sesuai kebutuhan, dari jumlah kecil hingga pemesanan besar.', 'Produk', 34),
  ('Apakah tersedia jasa cetak brosur dan poster?', 'Ya, tersedia cetak brosur, poster, dan media promosi cetak lainnya dengan hasil tajam serta pilihan bahan yang dapat disesuaikan dengan kebutuhan dan budget.', 'Produk', 35),
  ('Apakah bisa cetak voucher custom yang anti duplikasi atau pemalsuan?', 'Bisa. Elemen desain dan fitur keamanan sederhana bisa diterapkan agar voucher promosi tidak mudah dipalsukan, termasuk pola anti-duplikasi sesuai kebutuhan.', 'Produk', 36),
  ('Apakah bisa cetak spanduk bendera atau umbul-umbul untuk acara 17 Agustus dan HUT RI?', 'Bisa. Tersedia cetak spanduk bendera dan umbul-umbul untuk kebutuhan instansi, sekolah, RT/RW, maupun kantor. Disarankan memesan lebih awal menjelang 17 Agustus agar tidak kehabisan slot produksi.', 'Produk', 37),
  ('Bagaimana cara mengirim file desain untuk dicetak?', 'Setelah memilih produk, file desain bisa dikirim melalui WhatsApp atau email lalu dikonfirmasikan ke admin. Tim kami akan memeriksa file agar hasil cetak sesuai dengan kebutuhan Anda.', 'Desain', 38),
  ('Bagaimana cara menyiapkan file desain agar hasil cetak tidak pecah dan warna tetap tajam?', 'Banyak hasil cetak yang kurang maksimal bukan karena mesin, tetapi karena file desain belum sesuai standar cetak. Gunakan resolusi minimal 300 dpi dengan format AI, PSD, PDF, atau PNG, dan konsultasikan dengan tim sebelum mengirim file final.', 'Desain', 39),
  ('Apa saja tips memilih kertas atau bahan cetak yang tepat?', 'Pemilihan bahan sangat berpengaruh pada kualitas hasil cetak. Bahan yang cocok untuk brosur belum tentu cocok untuk kartu nama atau undangan. Konsultasikan dengan tim untuk menyesuaikan bahan dengan fungsi produk dan budget Anda.', 'Desain', 40),
  ('Bagaimana proses pembayaran?', 'Pembayaran dilakukan setelah pesanan dikonfirmasi oleh tim, kemudian proses produksi langsung dikerjakan. Metode pembayaran yang tersedia bisa ditanyakan langsung ke admin.', 'Pembayaran', 41),
  ('Apakah bisa kirim ke seluruh Indonesia?', 'Bisa. Pesanan dapat dikirim melalui ekspedisi ke seluruh Indonesia. Untuk area Jakarta Timur dan sekitarnya, pesanan juga bisa diambil langsung di lokasi.', 'Pengiriman', 42);
